// On-device proof for the per-level L1 refinement (shaders/align.comp).
//
// Usage: srp_proof_align <align.spv> <ref_dir>
// Runs SrpAlignL1Gpu on the real-burst 512-crop finest level pair
// (<ref_dir>/align_l1_{ref,mov,init,cpu,zero_cpu}.npy + align_l1_params.txt,
// generated by /tmp/gen_align_refs.py from the unmodified CPU source) in
// two cases: the true in-loop pre-L1 flow and a zero-init flow (3 tiles
// move — proves the search really runs). Gate: bit-exact integer flows vs
// cpu_l1_local_search (port policy §3). The zero case additionally runs
// twice to guard dispatch races. Prints numbers; exits nonzero on breach.

#include <cmath>
#include <cstdint>
#include <cstdio>
#include <cstring>
#include <string>
#include <vector>

#include <vulkan/vulkan.h>

#include "npy.h"
#include "srp_context.h"
#include "srp_pipeline.h"

namespace {

bool FindMemoryType(VkPhysicalDevice physical, uint32_t type_bits,
                    VkMemoryPropertyFlags flags, uint32_t* out_index) {
  VkPhysicalDeviceMemoryProperties props{};
  vkGetPhysicalDeviceMemoryProperties(physical, &props);
  for (uint32_t i = 0; i < props.memoryTypeCount; ++i) {
    if ((type_bits & (1u << i)) != 0u &&
        (props.memoryTypes[i].propertyFlags & flags) == flags) {
      *out_index = i;
      return true;
    }
  }
  return false;
}

bool MakeBuffer(VkDevice device, VkPhysicalDevice physical, VkDeviceSize bytes,
                const float* src, VkBuffer* out_buffer,
                VkDeviceMemory* out_memory) {
  VkBufferCreateInfo buffer_info{};
  buffer_info.sType = VK_STRUCTURE_TYPE_BUFFER_CREATE_INFO;
  buffer_info.size = bytes;
  buffer_info.usage = VK_BUFFER_USAGE_STORAGE_BUFFER_BIT;
  buffer_info.sharingMode = VK_SHARING_MODE_EXCLUSIVE;
  if (vkCreateBuffer(device, &buffer_info, nullptr, out_buffer) != VK_SUCCESS) {
    return false;
  }
  VkMemoryRequirements req{};
  vkGetBufferMemoryRequirements(device, *out_buffer, &req);
  uint32_t index = 0;
  if (!FindMemoryType(physical, req.memoryTypeBits,
                      VK_MEMORY_PROPERTY_HOST_VISIBLE_BIT |
                          VK_MEMORY_PROPERTY_HOST_COHERENT_BIT,
                      &index)) {
    vkDestroyBuffer(device, *out_buffer, nullptr);
    return false;
  }
  VkMemoryAllocateInfo alloc{};
  alloc.sType = VK_STRUCTURE_TYPE_MEMORY_ALLOCATE_INFO;
  alloc.allocationSize = req.size;
  alloc.memoryTypeIndex = index;
  if (vkAllocateMemory(device, &alloc, nullptr, out_memory) != VK_SUCCESS) {
    vkDestroyBuffer(device, *out_buffer, nullptr);
    return false;
  }
  if (vkBindBufferMemory(device, *out_buffer, *out_memory, 0) != VK_SUCCESS) {
    vkFreeMemory(device, *out_memory, nullptr);
    vkDestroyBuffer(device, *out_buffer, nullptr);
    return false;
  }
  void* mapped = nullptr;
  if (vkMapMemory(device, *out_memory, 0, bytes, 0, &mapped) != VK_SUCCESS) {
    return false;
  }
  if (src != nullptr) {
    std::memcpy(mapped, src, static_cast<size_t>(bytes));
  } else {
    std::memset(mapped, 0, static_cast<size_t>(bytes));
  }
  vkUnmapMemory(device, *out_memory);
  return true;
}

void FreeBuffer(VkDevice device, VkBuffer buffer, VkDeviceMemory memory) {
  if (buffer != VK_NULL_HANDLE) vkDestroyBuffer(device, buffer, nullptr);
  if (memory != VK_NULL_HANDLE) vkFreeMemory(device, memory, nullptr);
}

std::vector<uint8_t> ReadFile(const char* path) {
  std::vector<uint8_t> bytes;
  if (FILE* f = std::fopen(path, "rb")) {
    std::fseek(f, 0, SEEK_END);
    const long n = std::ftell(f);
    std::fseek(f, 0, SEEK_SET);
    if (n > 0) {
      bytes.resize(static_cast<size_t>(n));
      bytes.resize(std::fread(bytes.data(), 1, bytes.size(), f));
    }
    std::fclose(f);
  }
  return bytes;
}

bool RunL1(srp::Context* ctx, VkShaderModule module, uint32_t width,
           uint32_t height, uint32_t tile_count, uint32_t tile_size,
           uint32_t radius, uint32_t ntx, const std::vector<float>& ref,
           const std::vector<float>& mov, const std::vector<float>& flow_in,
           std::vector<float>* flow_out) {
  auto* device = static_cast<VkDevice>(srp::NativeDevice(ctx));
  auto* physical = static_cast<VkPhysicalDevice>(srp::NativePhysicalDevice(ctx));
  VkBuffer ref_buf = VK_NULL_HANDLE, mov_buf = VK_NULL_HANDLE,
           flow_buf = VK_NULL_HANDLE;
  VkDeviceMemory ref_mem = VK_NULL_HANDLE, mov_mem = VK_NULL_HANDLE,
                 flow_mem = VK_NULL_HANDLE;
  const VkDeviceSize img_bytes =
      static_cast<VkDeviceSize>(width) * height * sizeof(float);
  const VkDeviceSize flow_bytes =
      static_cast<VkDeviceSize>(tile_count) * 2 * sizeof(float);
  bool ok = false;
  if (MakeBuffer(device, physical, img_bytes, ref.data(), &ref_buf,
                 &ref_mem) &&
      MakeBuffer(device, physical, img_bytes, mov.data(), &mov_buf,
                 &mov_mem) &&
      MakeBuffer(device, physical, flow_bytes, flow_in.data(), &flow_buf,
                 &flow_mem) &&
      srp::SrpAlignL1Gpu(ctx, width, height, tile_count, tile_size, radius,
                         ntx, ref_buf, mov_buf, flow_buf,
                         module) == srp::Status::kOk) {
    void* mapped = nullptr;
    if (vkMapMemory(device, flow_mem, 0, flow_bytes, 0, &mapped) ==
        VK_SUCCESS) {
      const size_t n = static_cast<size_t>(tile_count) * 2;
      flow_out->assign(static_cast<const float*>(mapped),
                       static_cast<const float*>(mapped) + n);
      vkUnmapMemory(device, flow_mem);
      ok = true;
    }
  }
  FreeBuffer(device, ref_buf, ref_mem);
  FreeBuffer(device, mov_buf, mov_mem);
  FreeBuffer(device, flow_buf, flow_mem);
  return ok;
}

bool CheckExact(const char* name, const std::vector<float>& got,
                const std::vector<float>& want) {
  if (got.size() != want.size()) {
    std::fprintf(stderr, "FAIL %s: size %zu vs %zu\n", name, got.size(),
                 want.size());
    return false;
  }
  uint64_t ndiff = 0;
  float maxabs = 0.0f;
  for (size_t i = 0; i < got.size(); ++i) {
    const float d = std::fabs(got[i] - want[i]);
    if (d != 0.0f) {
      ++ndiff;
      maxabs = std::fmax(maxabs, d);
    }
  }
  const bool pass = ndiff == 0;
  std::printf("%s: n=%zu ndiff=%llu maxabs=%.6g (bit-exact) %s\n", name,
              got.size(), static_cast<unsigned long long>(ndiff),
              static_cast<double>(maxabs), pass ? "PASS" : "FAIL");
  return pass;
}

}  // namespace

int main(int argc, char** argv) {
  if (argc != 3) {
    std::fprintf(stderr, "usage: %s <align.spv> <ref_dir>\n", argv[0]);
    return 2;
  }
  const std::string ref_dir = argv[2];
  auto load = [&](const char* name, srp_proof::NpyArray* out) {
    return srp_proof::LoadNpy((ref_dir + "/" + name).c_str(), out);
  };

  srp_proof::NpyArray ref, mov, init, cpu, zero_cpu;
  if (!load("align_l1_ref.npy", &ref) || !load("align_l1_mov.npy", &mov) ||
      !load("align_l1_init.npy", &init) || !load("align_l1_cpu.npy", &cpu) ||
      !load("align_l1_zero_cpu.npy", &zero_cpu)) {
    std::fprintf(stderr, "FAIL: align refs missing\n");
    return 1;
  }
  uint32_t tile_size = 0, radius = 0;
  {
    const std::vector<uint8_t> text =
        ReadFile((ref_dir + "/align_l1_params.txt").c_str());
    if (text.empty() ||
        std::sscanf(reinterpret_cast<const char*>(text.data()),
                    "tile_size=%u search_radius=%u", &tile_size, &radius) !=
            2) {
      std::fprintf(stderr, "FAIL: cannot parse align_l1_params.txt\n");
      return 1;
    }
  }
  const uint32_t h = static_cast<uint32_t>(ref.shape[0]);
  const uint32_t w = static_cast<uint32_t>(ref.shape[1]);
  const uint32_t nty = static_cast<uint32_t>(init.shape[0]);
  const uint32_t ntx = static_cast<uint32_t>(init.shape[1]);
  const uint32_t tc = nty * ntx;
  std::printf("level %ux%u tiles %ux%u=%u tile_size=%u radius=%u\n", w, h, ntx,
              nty, tc, tile_size, radius);

  srp::Context* ctx = nullptr;
  if (srp::Create(&ctx) != srp::Status::kOk || ctx == nullptr) {
    std::fprintf(stderr, "FAIL: srp::Create failed\n");
    return 1;
  }
  std::printf("device: %s\n", srp::DeviceInfo(ctx).c_str());
  auto* device = static_cast<VkDevice>(srp::NativeDevice(ctx));

  const std::vector<uint8_t> spirv = ReadFile(argv[1]);
  if (spirv.empty() || spirv.size() % 4 != 0) {
    std::fprintf(stderr, "FAIL: cannot read spv %s\n", argv[1]);
    srp::Destroy(ctx);
    return 1;
  }
  VkShaderModuleCreateInfo module_info{};
  module_info.sType = VK_STRUCTURE_TYPE_SHADER_MODULE_CREATE_INFO;
  module_info.codeSize = spirv.size();
  module_info.pCode = reinterpret_cast<const uint32_t*>(spirv.data());
  VkShaderModule module = VK_NULL_HANDLE;
  if (vkCreateShaderModule(device, &module_info, nullptr, &module) != VK_SUCCESS) {
    std::fprintf(stderr, "FAIL: shader module create failed\n");
    srp::Destroy(ctx);
    return 1;
  }

  int failures = 0;
  std::vector<float> got;
  // Case 1: true in-loop pre-L1 flow (in-loop fidelity).
  if (!RunL1(ctx, module, w, h, tc, tile_size, radius, ntx, ref.data,
             mov.data, init.data, &got) ||
      !CheckExact("alignL1_preflow", got, cpu.data)) {
    ++failures;
  }
  // Case 2: zero-init flow (tiles really move) + repeat for determinism.
  std::vector<float> zeros(tc * 2, 0.0f);
  std::vector<float> got2;
  if (!RunL1(ctx, module, w, h, tc, tile_size, radius, ntx, ref.data,
             mov.data, zeros, &got) ||
      !CheckExact("alignL1_zeroinit", got, zero_cpu.data)) {
    ++failures;
  } else if (!RunL1(ctx, module, w, h, tc, tile_size, radius, ntx, ref.data,
                    mov.data, zeros, &got2) ||
             !CheckExact("alignL1_zeroinit_repeat", got2, got)) {
    ++failures;
  }

  vkDestroyShaderModule(device, module, nullptr);
  srp::Destroy(ctx);
  if (failures == 0) std::printf("PASS: align-L1 on-device bit-exact\n");
  return failures == 0 ? 0 : 1;
}
